{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each product and quarter, is the contract reservation a minimum delivery requirement (i.e., you must deliver at least that many units that quarter, with any shortfall incurring the delay compensation), or is it an exact target that must be met precisely?"
  ],
  "rationale": "The response asks a single clarification question regarding the nature of the contract reservation (minimum vs. exact target)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a unit is delayed (delivered in a later quarter than its reservation quarter), is the delay compensation charged for each quarter of delay (e.g., a unit reserved in Q1 but delivered in Q3 costs 2 quarters of compensation), or is it a one-time flat charge regardless of how late it is delivered?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive compensation structures (per-quarter vs. flat charge), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a unit reserved in a given quarter be delivered in an earlier quarter (i.e., can you produce and deliver ahead of the reservation quarter), or must each unit be delivered in its reservation quarter or later?"
  ],
  "rationale": "The response asks for a single policy choice regarding delivery timing relative to the reservation quarter."
}

{
  "action": "question",
  "question_count": 1,
